package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func modpow(a, e int) int {
	res := 1
	for e > 0 {
		if e&1 == 1 {
			res = (res * a) % MOD
		}
		a = (a * a) % MOD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int
	fmt.Fscan(in, &n, &k)

	maxN := 505
	C := make([][]int, maxN)
	for i := 0; i < maxN; i++ {
		C[i] = make([]int, maxN)
		C[i][0] = 1
		for j := 1; j <= i; j++ {
			C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
		}
	}

	Pow2 := make([]int, maxN*maxN)
	Pow2[0] = 1
	for i := 1; i < len(Pow2); i++ {
		Pow2[i] = (Pow2[i-1] * 2) % MOD
	}

	A := make([]int, n+2)
	for i := 1; i <= n; i++ {
		for j := i; j <= n; j++ {
			inside := (j - i + 1) * (j - i + 2) / 2
			A[i] = (A[i] + Pow2[inside]) % MOD
		}
	}

	dp := make([][]int, n+2)
	for i := range dp {
		dp[i] = make([]int, k+2)
	}
	dp[0][0] = 1

	for i := 1; i <= n; i++ {
		for j := 0; j <= k; j++ {
			dp[i][j] = dp[i-1][j]
		}
		for l := 1; l <= i; l++ {
			cnt := 0
			for r := l; r <= i; r++ {
				cnt++
			}
			inside := cnt * (cnt + 1) / 2
			ways := Pow2[inside]
			for j := 1; j <= k; j++ {
				dp[i][j] = (dp[i][j] + dp[l-1][j-1]*ways) % MOD
			}
		}
	}

	ans := dp[n][k]
	if k > 0 {
		ans = (ans - dp[n][k-1] + MOD) % MOD
	}
	fmt.Println(ans)
}
